def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = 7
    ref = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not ref:
        return [row[:] for row in grid]

    rs = [r for r, c in ref]
    cs = [c for r, c in ref]
    if len(set(rs)) == 1:
        orient = "h"
        intercept = lambda r, c: r
    elif len(set(cs)) == 1:
        orient = "v"
        intercept = lambda r, c: c
    elif all(r + c == ref[0][0] + ref[0][1] for r, c in ref):
        orient = "neg"
        intercept = lambda r, c: r + c
    else:
        orient = "pos"
        intercept = lambda r, c: r - c

    ref_intercept = intercept(*ref[0])
    out = [[bg] * w for _ in range(h)]

    # Keep the reference line in place.
    for r, c in ref:
        out[r][c] = 8

    colors = set(grid[r][c] for r in range(h) for c in range(w)) - {bg, 8}
    for color in colors:
        offsets = {intercept(r, c) for r in range(h) for c in range(w)
                   if grid[r][c] == color}
        for target in offsets:
            delta = target - ref_intercept
            if orient == "h":
                dr, dc = delta, 0
            elif orient == "v":
                dr, dc = 0, delta
            elif orient == "neg":
                if delta % 2:
                    continue
                dr = dc = delta // 2
            else:
                if delta % 2:
                    continue
                dr, dc = delta // 2, -delta // 2

            for r, c in ref:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    out[nr][nc] = color

    return out
